'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat32Array = require( '@stdlib/assert/is-same-float32array' );
var Float32Array = require( '@stdlib/array/float32' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var resolveTriangle = require( '@stdlib/blas/base/matrix-triangle-resolve-enum' );
var resolveTranspose = require( '@stdlib/blas/base/transpose-operation-resolve-enum' );
var resolveDiagonal = require( '@stdlib/blas/base/diagonal-type-resolve-enum' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var strsv = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float32', buffer, [ length ], [ stride ], offset, 'row-major' );
}

/**
* Returns a two-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} N - number of rows and columns
* @param {integer} stride0 - stride of the first dimension
* @param {integer} stride1 - stride of the second dimension
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} two-dimensional ndarray
*/
function matrix( buffer, N, stride0, stride1, offset ) {
	return new ndarray( 'float32', buffer, [ N, N ], [ stride0, stride1 ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof strsv, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( strsv.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function solves the system of equations `A*x = b` (upper, no-transpose, non-unit)', function test( t ) {
	var expected;
	var trans;
	var diag;
	var uplo;
	var xbuf;
	var Abuf;
	var x;
	var A;
	var v;

	xbuf = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	Abuf = new Float32Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 5.0, 0.0, 0.0, 6.0 ] );
	x = vector( xbuf, 3, 1, 0 );
	A = matrix( Abuf, 3, 3, 1, 0 );

	uplo = scalar2ndarray( resolveTriangle( 'upper' ), {
		'dtype': 'int32'
	});
	trans = scalar2ndarray( resolveTranspose( 'no-transpose' ), {
		'dtype': 'int32'
	});
	diag = scalar2ndarray( resolveDiagonal( 'non-unit' ), {
		'dtype': 'int32'
	});

	v = strsv( [ x, A, uplo, trans, diag ] );

	expected = new Float32Array( [ -0.25, -0.125, 0.5 ] );
	t.strictEqual( v, x, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( getData( v ), expected ), true, 'returns expected value' );

	t.end();
});

