tape( 'the function supports ndarrays having non-zero offsets', function test( t ) {
	var expected;
	var trans;
	var diag;
	var uplo;
	var xbuf;
	var Abuf;
	var x;
	var A;
	var v;

	xbuf = new Float32Array([
		0.0,
		1.0, // 0
		0.0,
		2.0, // 1
		0.0,
		3.0  // 2
	]);
	x = vector( xbuf, 3, 2, 1 );

	Abuf = new Float32Array([
		999.0,
		999.0,
		1.0,
		2.0,
		3.0,
		0.0,
		4.0,
		5.0,
		0.0,
		0.0,
		6.0
	]);
	A = matrix( Abuf, 3, 3, 1, 2 );

	uplo = scalar2ndarray( resolveTriangle( 'upper' ), {
		'dtype': 'int32'
	});
	trans = scalar2ndarray( resolveTranspose( 'no-transpose' ), {
		'dtype': 'int32'
	});
	diag = scalar2ndarray( resolveDiagonal( 'non-unit' ), {
		'dtype': 'int32'
	});

	v = strsv( [ x, A, uplo, trans, diag ] );

	expected = new Float32Array([
		0.0,
		-0.25,
		0.0,
		-0.125,
		0.0,
		0.5
	]);
	t.strictEqual( v, x, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( getData( v ), expected ), true, 'returns expected value' );
	t.end();
});
